#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* convertToBase7(int num){
    static char out[32];
    char d[32];
    int len=0,pos=0;
    if(num==0){strcpy(out,"0");return out;}
    long long x=llabs((long long)num);
    while(x>0){d[len++]=(char)('0'+x%7);x/=7;}
    if(num<0)out[pos++]='-';
    for(int i=len-1;i>=0;i--)out[pos++]=d[i];
    out[pos]='\0';
    return out;
}

