class Solution{
public:
    string convertToBase7(int num){
        if(num==0)return "0";
        bool neg=num<0;
        long long x=llabs((long long)num);
        string s;
        while(x>0){s.push_back(char('0'+x%7));x/=7;}
        reverse(s.begin(),s.end());
        if(neg)s="-"+s;
        return s;
    }
};

