class Solution{
    public String convertToBase7(int num){
        if(num==0)return "0";
        boolean neg=num<0;
        long x=Math.abs((long)num);
        StringBuilder s=new StringBuilder();
        while(x>0){s.append(x%7);x/=7;}
        s.reverse();
        if(neg)s.insert(0,'-');
        return s.toString();
    }
}

